CREATE OR REPLACE FUNCTION public.notify_staff_notification_push() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$ DECLARE v_secret text; BEGIN SELECT secret INTO v_secret FROM public.internal_push_auth WHERE id=1; PERFORM net.http_post(url:='https://project--5e1fe153-4c10-4ade-8c98-e355fcdea791.lovable.app/api/public/hooks/staff-notification-push',headers:=jsonb_build_object('Content-Type','application/json','x-staff-push-secret',v_secret,'apikey','eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJIUzI1NiIsInJlZiI6InZ6cmJkYXdscXllYWxubHJ0d2dqIiwicm9sZSI6ImFub24iLCJpYXQiOjE3Nzg2OTA5NDIsImV4cCI6MjA5NDI2Njk0Mn0.uZD07rXDfXt-g3mEMlhS-m_784yaID0-cabPobpMIoE'),body:=jsonb_build_object('id',NEW.id::text)); RETURN NEW; EXCEPTION WHEN OTHERS THEN RETURN NEW; END; $$;